 1→import { useEffect, useRef } from 'react';
 2→import { useTranslation } from '../LanguageContext';
 3→import { useAgent } from '../useAgent';
 4→import { ChatInput } from './ChatInput';
 5→import { MessageBubble } from './MessageBubble';
