 1→import { createContext, useContext, useState, useEffect, useCallback, type ReactNode } from 'react';
 2→import en from './i18n/en.json';
 3→import zhTW from './i18n/zh-TW.json';
 4→
 5→export type Language = 'en' | 'zh-TW';
 6→
 7→const translations: Record<Language, Record<string, string>> = {
 8→  'en': en,
 9→  'zh-TW': zhTW,
10→};
11→
12→interface LanguageContextValue {
13→  language: Language;
14→  setLanguage: (lang: Language) => void;
15→  t: (key: string, params?: Record<string, string | number>) => string;
16→}
17→
18→const LanguageContext = createContext<LanguageContextValue | null>(null);
19→
20→function getInitialLanguage(): Language {
21→  const stored = localStorage.getItem('language');
22→  if (stored === 'en' || stored === 'zh-TW') return stored;
23→  if (navigator.language.startsWith('zh')) return 'zh-TW';
24→  return 'en';
25→}
26→
27→export function LanguageProvider({ children }: { children: ReactNode }) {
28→  const [language, setLanguageState] = useState<Language>(getInitialLanguage);
29→
30→  useEffect(() => {
31→    document.documentElement.setAttribute('lang', language === 'zh-TW' ? 'zh-Hant' : 'en');
32→    localStorage.setItem('language', language);
33→  }, [language]);
34→
35→  const setLanguage = useCallback((lang: Language) => {
36→    setLanguageState(lang);
37→  }, []);
38→
39→  const t = useCallback((key: string, params?: Record<string, string | number>): string => {
40→    let value = translations[language][key] ?? key;
41→    if (params) {
42→      for (const [paramKey, paramValue] of Object.entries(params)) {
43→        value = value.replace(new RegExp(`\\{${paramKey}\\}`, 'g'), String(paramValue));
44→      }
45→    }
46→    return value;
47→  }, [language]);
48→
49→  return (
50→    <LanguageContext.Provider value={{ language, setLanguage, t }}>
51→      {children}
52→    </LanguageContext.Provider>
53→  );
54→}
55→
56→export function useTranslation() {
57→  const ctx = useContext(LanguageContext);
58→  if (!ctx) throw new Error('useTranslation must be used within LanguageProvider');
59→  return ctx;
60→}
