          <p className="file-upload__text">
            {t('uploadDropText')}
          </p>
        )}
      </div>
      <div className="file-upload-divider">
        <span>{t('uploadOr')}</span>
      </div>
      <button
        className="file-upload-sample-btn"
        onClick={handleLoadSample}
        disabled={loadingSample}
      >
        {loadingSample ? t('loading') : t('loadSample')}
      </button>
    </div>
  );
}

